"""Read the fixtures generated by ``tools/ggb_oracle/GgbOracleTest.java``."""
from __future__ import annotations

import json
from pathlib import Path
from typing import Any

FIXTURE_DIR = Path(__file__).parent / "fixtures" / "ggb_oracle"


def names() -> list[str]:
    return sorted(path.stem for path in FIXTURE_DIR.glob("*.json"))


def load(name: str) -> dict[str, Any]:
    return json.loads((FIXTURE_DIR / f"{name}.json").read_text(encoding="utf-8"))


def sympy_expr(text: str) -> Any:
    """Parse a GGB expression from the fixtures into sympy (same syntax, no GGB algebra)."""
    from sympy import Abs, E, cos, log, sin, tan
    from sympy.parsing.sympy_parser import parse_expr

    local = {
        "e": E,
        "ln": log,
        "abs": Abs,
        "cot": lambda value: 1 / tan(value),
        "sec": lambda value: 1 / cos(value),
        "csc": lambda value: 1 / sin(value),
    }
    return parse_expr(text.replace("^", "**"), local_dict=local, evaluate=True)
